    out = [row[:] for row in grid]

    # The most frequent color is the background; enclosed regions of it
    # must not be mistaken for frames themselves.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue

            cellset = set(cells)
            border = (
                {(r0, x) for x in range(c0, c1 + 1)} |
                {(r1, x) for x in range(c0, c1 + 1)} |
                {(y, c0) for y in range(r0, r1 + 1)} |
                {(y, c1) for y in range(r0, r1 + 1)}
            )
            if not border.issubset(cellset):
                continue

